// slider: position 0..1000 for a year, stretched so the recent centuries get as much room as the ancient millennia
const ANCH = [[-10000, 0], [-3000, 50], [-500, 150], [500, 260], [1500, 430], [1800, 640], [1900, 760], [1950, 860], [2025, 1000]];
export const yearToPos = (y) => {
  if (y <= ANCH[0][0]) return 0;
  for (let i = 1; i < ANCH.length; i++) if (y <= ANCH[i][0]) { const [y0, p0] = ANCH[i - 1], [y1, p1] = ANCH[i]; return p0 + ((y - y0) / (y1 - y0)) * (p1 - p0); }
  return 1000;
};
export const posToYear = (p) => {
  for (let i = 1; i < ANCH.length; i++) if (p <= ANCH[i][1]) { const [y0, p0] = ANCH[i - 1], [y1, p1] = ANCH[i]; return y0 + ((p - p0) / (p1 - p0)) * (y1 - y0); }
  return 2025;
};
export const fmtYear = (y) => (y < 0 ? `${Math.round(-y).toLocaleString('en-US')} BCE` : `${Math.round(y)}`);

export const ACTIVE = ['math', 'cs', 'phys', 'chem', 'bio', 'med'];
export const NODES = RAW.filter((r) => ACTIVE.includes(r.k)).map((r) => ({ ...r, lat: r.p[0], lon: r.p[1], pos: yearToPos(r.y), from: r.from ? r.from.split(' ') : [] }))
  .sort((a, b) => a.y - b.y || a.n.localeCompare(b.n));
const IDX = Object.fromEntries(NODES.map((n, i) => [n.id, i]));
NODES.forEach((n) => { n.from = n.from.filter((f) => f in IDX); }); // links to branches not shown yet are dropped
// [from, to] pairs by index; an arc for each "built on" relation
export const LINKS = NODES.flatMap((n, i) => n.from.filter((f) => f in IDX).map((f) => [IDX[f], i]));
export const NODE_INDEX = IDX;
